import type OpenFin from '@openfin/core';

import { workspaceBuildVersion } from '@common/utils/env';
import { currentOFIdentity, homeOFIdentity } from '@common/utils/window';

import { wrapSync } from '@client-platform/index';
import { AttachedPage, WorkspacePlatformModule } from '@client-platform/shapes';

export interface RegisterUsageStatus {
    apiVersion?: string;
    componentVersion?: string;
    allowed: boolean;
    rejectionCode?: string;
}

interface RegisterUsageRequest extends RegisterUsageStatus {
    componentName: string;
    componentVersion?: string;
}

export enum ComponentName {
    Browser = 'Browser',
    Dock = 'Dock',
    EnterpriseDock = 'EnterpriseDock',
    Home = 'Home',
    Notification = 'Notification',
    Storefront = 'Storefront',
    Platform = 'Platform',
    Theming = 'Theming',
    Microflow = 'Microflow'
}

const registerUsage = async (
    name: ComponentName | `${ComponentName.Microflow}:${string}`,
    status: RegisterUsageStatus,
    type: 'workspace-licensing' | 'integration-feature' = 'workspace-licensing'
) => {
    const request: RegisterUsageRequest = {
        apiVersion: status.apiVersion || workspaceBuildVersion,
        componentName: name,
        componentVersion: status.componentVersion || workspaceBuildVersion,
        allowed: status.allowed,
        rejectionCode: status.rejectionCode
    };
    fin.System.registerUsage({
        type,
        data: request
    });
};

let browserUsageRegistered = false;

export const registerBrowserUsage = (status: RegisterUsageStatus) => {
    if (!browserUsageRegistered) {
        browserUsageRegistered = true;
        registerUsage(ComponentName.Browser, status);
    }
};

export const registerHomeUsage = (status: RegisterUsageStatus) => {
    if (homeOFIdentity.uuid !== currentOFIdentity.uuid || homeOFIdentity.name !== currentOFIdentity.name) {
        registerUsage(ComponentName.Home, status);
    }
};

export const registerStorefrontUsage = (status: RegisterUsageStatus) => {
    registerUsage(ComponentName.Storefront, status);
};

export const registerDockUsage = (status: RegisterUsageStatus) => {
    registerUsage(ComponentName.Dock, status);
};

export const registerNotificationUsage = (status: RegisterUsageStatus) => {
    registerUsage(ComponentName.Notification, status);
};

export const registerPlatformUsage = (status: RegisterUsageStatus) => {
    registerUsage(ComponentName.Platform, status);
};

export const registerThemingUsage = (status: RegisterUsageStatus) => {
    registerUsage(ComponentName.Theming, status);
};

export const registerMicroflowUsage = (microflowName: string, status: RegisterUsageStatus) => {
    registerUsage(`${ComponentName.Microflow}:${microflowName}`, status, 'integration-feature');
};

export type AnalyticsSource =
    | 'Browser'
    | 'Dock'
    | 'Home'
    | 'Notification'
    | 'Store'
    | 'Platform'
    | 'Theming'
    | 'Interop';

/**
 * Event for analytics
 */
export type AnalyticsEvent = {
    source: AnalyticsSource;
    type: string;
    action: string;
    value?: string;
    entityId?: OpenFin.Identity;
    data?: any;
};

export interface AnalyticsEventInternal extends AnalyticsEvent {
    /**
     * By default, all event values are redacted before sending to OF.
     * For events not containing any identifiable information, set this to true.
     */
    skipValueHashing?: boolean;
}
export type AnalyticsEventRaise = Omit<AnalyticsEventInternal, 'source'>;

const platformMap: Map<string, WorkspacePlatformModule> = new Map();
const getPlatformById = (platformIdentity: OpenFin.Identity): WorkspacePlatformModule | null => {
    if (!platformIdentity?.uuid) {
        console.warn('getPlatformById called with invalid platformIdentity');
        return null;
    }
    let platform = platformMap.get(platformIdentity.uuid);
    if (!platform) {
        platform = wrapSync(platformIdentity);
        platform.once('closed', () => {
            platformMap.delete(platformIdentity.uuid);
        });
        platformMap.set(platformIdentity.uuid, platform);
    }
    return platform;
};

const raiseAnalytics = async (platform: WorkspacePlatformModule | null, payload: AnalyticsEventInternal) => {
    if (!platform) return;
    try {
        // eslint-disable-next-line no-underscore-dangle
        await platform._raiseAnalytics([payload]);
    } catch (err) {
        console.error('failed to raise analytics event', err);
    }
};

export const raiseBrowserAnalytics = async (payload: AnalyticsEventRaise) => {
    await raiseAnalytics(getPlatformById(fin.me.identity), { source: 'Browser', ...payload });
};

export const raiseBrowserPageAnalytics = async (pages: AttachedPage[], action: string) => {
    for (const page of pages) {
        raiseBrowserAnalytics({
            type: 'Page',
            action: action,
            value: page.title,
            data: { uuid: page.pageId }
        });
    }
};

export const raiseHomeAnalytics = async (platformIdentity: OpenFin.Identity, payload: AnalyticsEventRaise) => {
    await raiseAnalytics(getPlatformById(platformIdentity), { source: 'Home', ...payload });
};

export const raiseDockAnalytics = async (platformIdentity: OpenFin.Identity, payload: AnalyticsEventRaise) => {
    await raiseAnalytics(getPlatformById(platformIdentity), { source: 'Dock', ...payload });
};

export const raiseStorefrontAnalytics = async (platformIdentity: OpenFin.Identity, payload: AnalyticsEventRaise) => {
    await raiseAnalytics(getPlatformById(platformIdentity), { source: 'Store', ...payload });
};

export const raiseInteropAnalytics = async (payload: AnalyticsEventRaise) => {
    await raiseAnalytics(getPlatformById(fin.me.identity), { source: 'Interop', ...payload });
};
