import { useCallback } from 'react';
import { useTranslation } from 'react-i18next';

import styled from 'styled-components';

import { H2, Icon } from '@openfin/ui-library';

import CloseButtonLarge from '@common/components/CloseButton/CloseButtonLarge';

import { SidePanelComponent, useSidePanelContext } from '@enterprise/context/SidePanelContext';
import { useBookmarksPanelFocus } from '@enterprise/hooks/useBookmarksPanelFocus';

const BookmarksPanelHeader = ({ onClose }: { onClose?: () => void }) => {
    const { t } = useTranslation();
    const { toggleSidePanelComponent } = useSidePanelContext();
    const { focusButton } = useBookmarksPanelFocus();

    const handleCloseClick = useCallback(() => {
        if (onClose) {
            onClose();
        } else {
            toggleSidePanelComponent(SidePanelComponent.Bookmarks);
        }
        focusButton();
    }, []);

    return (
        <Container className="bookmarks-panel-header-container">
            <LeftContainer className="bookmarks-panel-header-left">
                <Icon icon="BookmarkFilled" />
                <Title className="bookmarks-panel-header-title">{t('bookmarks.bookmarks')}</Title>
            </LeftContainer>
            <CloseButtonLarge onClick={handleCloseClick} aria-label={t('bookmarks.closePanel')} />
        </Container>
    );
};

export default BookmarksPanelHeader;

const Title = styled(H2)`
    font-size: ${({ theme }) => theme.fontSize.base};
    font-weight: normal;
    color: var(--color-enterprise-side-panel-text-base);
    line-height: ${({ theme }) => theme.lineHeight.text};
`;

const Container = styled.div`
    height: 48px;
    width: 100%;
    padding: 0 ${({ theme }) => theme.px.base};
    border-bottom: 1px solid var(--color-enterprise-side-panel-border);

    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-shrink: 0;
`;

const LeftContainer = styled.div`
    display: flex;
    gap: ${({ theme }) => theme.px.xsmall};
    align-items: center;

    svg {
        margin-top: -1px;

        path {
            fill: var(--color-enterprise-side-panel-icon);
        }
    }
`;
